  /// never pruned.
  static const defaultMaxRetainedExitedJobs = 100;

  /// The exited-entry retention cap; see [defaultMaxRetainedExitedJobs].
  final int maxRetainedExitedJobs;

  /// The environment jobs run in.
  final ExecutionEnv env;

