      env.jobs.single.complete(0);
      await _pumpSettles();
      final stale = '${entry.id.substring(0, entry.id.length - 2)}zz';
      final result = await tool.execute(_args('output', id: stale), null, null);
      final text = _text(result);
      expect(text, contains('built ok'));
