        env.jobs[i].complete(0);
      }
      await _pumpSettles();
      final result = await tool.execute(
        _args('output', id: 'sh-9-nope'),
        null,
        null,
      );
      final text = _text(result);
      expect(text, contains('never registered'));
      // The hint is bounded: exactly 3 candidate rows regardless of the
